#!/usr/bin/env node
/**
 * Generates the tool reference in docs/tools/ from src/generated/operations.json
 * (which scripts/generate.mjs derives from ClickUp's OpenAPI specs).
 *
 *   docs/tools/README.md       index: every toolset and tool, with HTTP method/path
 *   docs/tools/<toolset>.md    per-tool details: description, parameters, body fields
 *
 * Run via `npm run generate`. Do not edit the output by hand.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ops = JSON.parse(fs.readFileSync(path.join(root, "src/generated/operations.json"), "utf8"));
const outDir = path.join(root, "docs/tools");

const BANNER = "<!-- Generated by scripts/generate-docs.mjs from ClickUp's OpenAPI specs. Do not edit by hand: run `npm run generate`. -->";
const MAX_DEPTH = 2; // body fields: top level + two levels of nesting (e.g. custom_fields[].value)

const anchor = (s) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9 _-]/g, "")
    .replace(/ /g, "-");

// ClickUp's docs cross-reference endpoints as (ref:operationId); generate.mjs turns that into "(see operationId)".
const byOpId = new Map(ops.map((o) => [o.operationId.toLowerCase().replace(/'/g, ""), o]));
const refTarget = (id, fromToolset) => {
  const o = byOpId.get(id.toLowerCase().replace(/'/g, ""));
  return o && { o, href: `${o.toolset === fromToolset ? "" : `${o.toolset}.md`}#${anchor(o.name)}` };
};

/** Turn "(see opId)" references into links to that tool's docs (or drop them if the target doesn't exist). */
const linkRefs = (text, fromToolset) =>
  text
    .replace(/\]\(doc:([^)\s]+)\)/g, "](https://developer.clickup.com/docs/$1)") // readme.io guide links
    .replace(/\]\((?:#tag\/[^/)]+\/operation\/|red:)([A-Za-z0-9_']+)\)/g, "](see $1)") // other endpoint-link spellings
    .replace(/\[([^\]]+)\]\(see ([A-Za-z0-9_']+)\)/g, (m, label, id) => {
      const t = refTarget(id, fromToolset);
      return t ? `[${label}](${t.href})` : label;
    })
    .replace(/\s?\(see ([A-Za-z0-9_']+)\)/g, (m, id) => {
      const t = refTarget(id, fromToolset);
      return t ? ` (see [\`${t.o.name}\`](${t.href}))` : "";
    });

/** Markdown-table-safe single line. */
const cell = (s = "", toolset = "", max = 300) => {
  let t = String(s)
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (t.length > max) t = t.slice(0, max - 1).trimEnd() + "…";
  return linkRefs(t, toolset).replace(/\|/g, "&#124;"); // entity, not "\|": avoids interacting with backslashes in the text
};

/** Free text for a paragraph: drop the leading summary and trailing "ClickUp API vX: ..." line we render separately. */
const prose = (op) => {
  const parts = op.description.split("\n\n").filter((p) => p.trim() !== op.summary.trim() && !/^ClickUp API v[23]: /.test(p));
  const text = parts
    .join("\n\n")
    .replace(/[ \t]+$/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/^#{1,6}\s+(.+?)\s*#*$/gm, "**$1**"); // demote headings so they don't break the page outline
  return linkRefs(text, op.toolset).trim();
};

function typeOf(s) {
  if (!s || typeof s !== "object") return "any";
  if (s.enum) return s.enum.map((v) => `\`${JSON.stringify(v)}\``).join(" \\| ");
  const alts = s.anyOf || s.oneOf;
  if (alts) return [...new Set(alts.map(typeOf))].join(" \\| ");
  const t = Array.isArray(s.type) ? s.type.filter((x) => x !== "null").join(" \\| ") : s.type;
  if (t === "array") return `${typeOf(s.items)}[]`;
  if (t) return t;
  if (s.properties) return "object";
  if (s.allOf) return "object";
  return "any";
}

function constraints(s) {
  const c = [];
  if (s.default !== undefined) c.push(`default \`${JSON.stringify(s.default)}\``);
  if (s.format) c.push(s.format);
  if (s.minimum !== undefined) c.push(`≥ ${s.minimum}`);
  if (s.maximum !== undefined) c.push(`≤ ${s.maximum}`);
  return c.length ? ` (${c.join(", ")})` : "";
}

/** Object-ish schema → its properties, merging allOf branches. */
function propsOf(s) {
  if (!s || typeof s !== "object") return { props: {}, required: [] };
  if (s.type === "array" || s.items) return propsOf(s.items);
  const props = { ...(s.properties || {}) };
  const required = [...(s.required || [])];
  for (const part of s.allOf || []) {
    const sub = propsOf(part);
    Object.assign(props, sub.props);
    required.push(...sub.required);
  }
  return { props, required };
}

function bodyRows(schema, toolset, prefix = "", depth = 0) {
  const rows = [];
  const { props, required } = propsOf(schema);
  for (const [name, s] of Object.entries(props)) {
    const full = prefix ? `${prefix}.${name}` : name;
    const isArr = s?.type === "array";
    rows.push(
      `| \`${full}${isArr ? "[]" : ""}\` | ${typeOf(s)} | ${required.includes(name) ? "yes" : ""} | ${cell(s?.description, toolset)}${constraints(s || {})} |`,
    );
    if (depth < MAX_DEPTH) rows.push(...bodyRows(s, toolset, `${full}${isArr ? "[]" : ""}`, depth + 1));
  }
  return rows;
}

const kind = (op) => (op.method === "GET" ? "read-only" : op.method === "DELETE" ? "destructive" : "write");
const badge = (op) => ({ "read-only": "🟢 read-only", write: "🟡 write", destructive: "🔴 destructive" })[kind(op)];

function toolSection(op) {
  const props = op.inputSchema.properties;
  const req = new Set(op.inputSchema.required || []);
  const out = [];
  out.push(`### \`${op.name}\``, "");
  out.push(`**${op.summary}** · \`${op.method} ${op.path}\` · API ${op.version} · ${badge(op)}${op.auth ? "" : " · no auth header"}`, "");
  const text = prose(op);
  if (text) out.push(text, "");

  const paramRows = op.params.map(
    (p) =>
      `| \`${p.key}\` | ${p.in}${p.style !== "plain" ? ` (${p.style})` : ""} | ${typeOf(props[p.key])} | ${req.has(p.key) ? "yes" : ""} | ${cell(props[p.key]?.description, op.toolset)}${constraints(props[p.key] || {})} |`,
  );
  if (op.body?.type === "multipart") {
    for (const k of ["file_path", "file_base64", "file_name", "form_fields"]) {
      paramRows.push(
        `| \`${k}\` | upload | ${typeOf(props[k])} | ${k === "file_path" ? "one of file_path / file_base64" : ""} | ${cell(props[k]?.description, op.toolset)} |`,
      );
    }
  }
  if (op.body?.type === "json") {
    paramRows.push(`| \`body\` | body | ${typeOf(props.body)} | ${req.has("body") ? "yes" : ""} | JSON request body, fields below. |`);
  }
  if (paramRows.length) {
    out.push("| Argument | In | Type | Required | Description |", "| --- | --- | --- | --- | --- |", ...paramRows, "");
  } else {
    out.push("_No arguments._", "");
  }

  if (op.body?.type === "json") {
    const rows = bodyRows(props.body, op.toolset);
    if (rows.length) {
      out.push("<details>", `<summary><code>body</code> fields (${rows.length})</summary>`, "");
      out.push("| Field | Type | Required | Description |", "| --- | --- | --- | --- |", ...rows, "", "</details>", "");
    }
  }
  if (op.body?.type === "multipart") {
    out.push(`Uploaded as multipart form field \`${op.body.fileField}\`.`, "");
  }
  return out.join("\n");
}

// ---- group ----
const byToolset = new Map();
for (const op of ops) {
  if (!byToolset.has(op.toolset)) byToolset.set(op.toolset, []);
  byToolset.get(op.toolset).push(op);
}
const toolsets = [...byToolset.keys()].sort();
const title = (t) => t.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());

fs.rmSync(outDir, { recursive: true, force: true });
fs.mkdirSync(outDir, { recursive: true });

// ---- per toolset ----
for (const t of toolsets) {
  const list = byToolset.get(t);
  const md = [
    BANNER,
    "",
    `# ${title(t)} tools`,
    "",
    `[← All tools](README.md) · ${list.length} tool${list.length === 1 ? "" : "s"} · enable with \`CLICKUP_TOOLSETS=${t}\``,
    "",
    "| Tool | HTTP | Kind |",
    "| --- | --- | --- |",
    ...list.map((op) => `| [\`${op.name}\`](#${anchor(op.name)}) | \`${op.method} ${op.path}\` | ${badge(op)} |`),
    "",
    ...list.map(toolSection),
  ];
  fs.writeFileSync(
    path.join(outDir, `${t}.md`),
    md
      .join("\n")
      .replace(/\n{3,}/g, "\n\n")
      .trimEnd() + "\n",
  );
}

// ---- index ----
const count = (fn) => ops.filter(fn).length;
const index = [
  BANNER,
  "",
  "# Tool reference",
  "",
  `All **${ops.length} tools** exposed by clickup-full-mcp (${count((o) => o.version === "v2")} from API v2, ${count((o) => o.version === "v3")} from API v3), generated from ClickUp's official OpenAPI specs.`,
  "",
  `🟢 read-only (GET): ${count((o) => kind(o) === "read-only")} · 🟡 write (POST/PUT/PATCH): ${count((o) => kind(o) === "write")} · 🔴 destructive (DELETE): ${count((o) => kind(o) === "destructive")}`,
  "",
  "How arguments work: path and query parameters go at the top level, JSON request bodies go in `body`, uploads take `file_path` or `file_base64`. See the [main README](../../README.md#how-tools-map-to-the-api).",
  "",
  "## Always-available tools",
  "",
  "| Tool | Mode | Description |",
  "| --- | --- | --- |",
  "| `clickup_request` | full + meta | Raw request to any `/api/v2/` or `/api/v3/` path with the configured token. Disable with `CLICKUP_ENABLE_RAW_REQUEST=false`. |",
  "| `clickup_search_operations` | meta | Search the operations below by keyword and optional toolset. |",
  "| `clickup_describe_operation` | meta | Full description and input schema of one operation. |",
  "| `clickup_call_operation` | meta | Call an operation by name with its arguments. |",
  "",
  "## Toolsets",
  "",
  "| Toolset | Tools | Read-only | Write | Destructive |",
  "| --- | --- | --- | --- | --- |",
  ...toolsets.map((t) => {
    const l = byToolset.get(t);
    const n = (k) => l.filter((o) => kind(o) === k).length || "";
    return `| [\`${t}\`](${t}.md) | ${l.length} | ${n("read-only")} | ${n("write")} | ${n("destructive")} |`;
  }),
  "",
  "## All tools",
  "",
];
for (const t of toolsets) {
  index.push(`### [${title(t)}](${t}.md)`, "", "| Tool | HTTP | Summary |", "| --- | --- | --- |");
  for (const op of byToolset.get(t)) {
    index.push(`| [\`${op.name}\`](${t}.md#${anchor(op.name)}) | \`${op.method} ${op.path}\` | ${cell(op.summary, "", 120)} |`);
  }
  index.push("");
}
fs.writeFileSync(path.join(outDir, "README.md"), index.join("\n").trimEnd() + "\n");

// ---- self-check: every relative link points at an existing file and heading ----
const slug = (h) =>
  h
    .toLowerCase()
    .replace(/[`*]/g, "")
    .replace(/[^a-z0-9 _-]/g, "")
    .replace(/ /g, "-");
const files = fs.readdirSync(outDir);
const headings = Object.fromEntries(
  files.map((f) => [f, new Set([...fs.readFileSync(path.join(outDir, f), "utf8").matchAll(/^#{1,6} (.+)$/gm)].map((m) => slug(m[1])))]),
);
const broken = [];
for (const f of files) {
  for (const [, href] of fs.readFileSync(path.join(outDir, f), "utf8").matchAll(/\]\(([^)\s]+)\)/g)) {
    if (/^(https?|mailto):/.test(href)) continue;
    const [file, hash] = href.split("#");
    const target = path.resolve(outDir, file || f);
    if (!fs.existsSync(target)) broken.push(`${f}: ${href}`);
    else if (hash && path.dirname(target) === outDir && !headings[path.basename(target)].has(hash)) broken.push(`${f}: ${href}`);
  }
}
if (broken.length) {
  console.error(`Broken links in docs/tools:\n  ${broken.join("\n  ")}`);
  process.exit(1);
}

const size = fs.readdirSync(outDir).reduce((n, f) => n + fs.statSync(path.join(outDir, f)).size, 0);
console.log(`Generated docs/tools/ (${toolsets.length + 1} files, ${(size / 1024).toFixed(0)} KB)`);
